              </el-table-column>
              <el-table-column prop="nameRight" label="姓名(右)" min-width="80" />
              <el-table-column prop="amountRight" label="预支数额(右)" min-width="100" align="right">
                <template #default="{ row }">{{ row.amountRight.toFixed(2) }}</template>
